var n=`0980-mandu`;var t=`world-0980`;var a=`KR`;var s=`east-asia`;var r=8;var o=54;var l={en:`Mandu`,ua:`Манду`};var g={en:`Mandu is a South Korea dish made with ground pork, tofu (firm), kimchi, garlic. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Манду, страва кухні країни Південна Корея. Основні складники: свинячий фарш, твердий тофу, кімчі, часник. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`ground-pork`,430,`g`],[`tofu-firm`,180,`g`],[`kimchi`,180,`g`],[`garlic`,4,`clove`],[`green-onion`,85,`g`],[`sesame-oil`,20,`ml`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:25,i:[[`dumpling-wrappers`,34,`pcs`]]},{en:`Put the prepared parcels in a steamer over gently boiling water, cover, and steam for about 14 minutes until the filling is completely cooked.`,ua:`Покладіть підготовлені вироби на решітку пароварки над водою, що ледь кипить, накрийте й готуйте на парі приблизно 14 хвилин до повної готовності начинки.`,t:[`steaming`],m:14,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`light-soy-sauce`,45,`ml`],[`rice-vinegar`,30,`ml`]]}];var m={slug:n,id:t,country:`KR`,region:s,servings:8,minutes:54,title:l,text:g,steps:d};export{a as country,m as default,t as id,o as minutes,s as region,r as servings,n as slug,d as steps,g as text,l as title};